style.css:
@-moz-document domain("discord.com") {
:root, .theme-dark {
    /* Text colors */
    --header-primary: #000000;
    --header-secondary: #000000;
    --text-normal: #000000;
    --text-muted: rgba(0, 0, 0, 0.6);
    --text-link: #000000;
    --channels-default: #000000;
    --interactive-normal: #000000;
    --interactive-hover: #000000;
    --interactive-active: #000000;
    --interactive-muted: rgba(0, 0, 0, 0.4);
    --channel-icon: #000000;
    --text-positive: #000000;

    /* Backgrounds */
    --background-primary: #ffe4e1;
    --background-secondary: #ffb6c1;
    --background-secondary-alt: #ffffe0;
    --background-tertiary: #ffffff;
    --background-accent: #ffb6c1;
    --background-floating: #ffe4e1;
    --background-message-hover: #ffffe0;
    --background-modifier-hover: #ffb6c1;
    --background-modifier-active: #ffb6c1;
    --background-modifier-selected: #ffffe0;
    --background-modifier-accent: #ffffff;

    /* UI Elements */
    --channeltextarea-background: #ffffff;
    --activity-card-background: #ffffe0;
    --deprecated-panel-background: #ffe4e1;
    --deprecated-card-bg: #ffb6c1;
    --deprecated-card-editable-bg: #ffffe0;
    --deprecated-store-bg: #ffe4e1;
    --home-background: #ffe4e1;
    --bg-overlay-chat: #ffffe0;

    /* Buttons */
    --primary-btn: #ffb6c1;
    --primary-btn-hover: #ffe4e1;
    --primary-btn-active: #ffffe0;
    --button-positive-background: #ffb6c1;
    --button-positive-background-hover: #ffffe0;
    --button-secondary-background-hover: #ffe4e1;
    --button-outline-primary-background: #ffffff;
    --button-outline-primary-border: #000000;
    --button-outline-primary-text: #000000;
    --button-outline-primary-background-hover: #ffffe0;
    --button-outline-primary-border-hover: #000000;
    --button-outline-primary-text-hover: #000000;

    /* Spoilers */
    --__spoiler-background-color--hidden: #ffe4e1;
    --__spoiler-border-color--hidden: #ffb6c1;
    --__spoiler-background-color--hidden--hover: #ffffe0;
    --__spoiler-border-color--hidden--hover: #ffffe0;

    /* Scrollbars */
    --scrollbar-thin-thumb: #ffb6c1;
    --scrollbar-thin-track: #ffffff;
    --scrollbar-auto-thumb: #ffe4e1;
    --scrollbar-auto-track: #ffffe0;
    --scrollbar-auto-scrollbar-color-thumb: #ffb6c1;
    --scrollbar-auto-scrollbar-color-track: #ffe4e1;

    /* Misc */
    --elevation-low: 0 1px 0 rgba(0, 0, 0, 0.1);
    --elevation-high: 0 8px 16px rgba(0, 0, 0, 0.2);
    --guild-header-text-shadow: none;
    --elevation-stroke: 0 0 0 1px rgba(0, 0, 0, 0.1);
  }
}
